import{d as p,C as a,o as g,c as d,a3 as s,E as e,j as n,a as h}from"./chunks/framework.Q4yG9rk_.js";const y=JSON.parse('{"title":"正易心法·第十二章","description":"《正易心法》第十二章——健顺动入，陷丽止说：八字不是八卦的专属标签，而是卦画结构的通用描述原则；以阖户（姤初）、辟户（复初）示范精确到爻。","frontmatter":{"title":"正易心法·第十二章","description":"《正易心法》第十二章——健顺动入，陷丽止说：八字不是八卦的专属标签，而是卦画结构的通用描述原则；以阖户（姤初）、辟户（复初）示范精确到爻。","category":"guide","aliases":["正易心法第十二章","健顺动入陷丽止说","八字非专属"],"source":["《正易心法》"],"outline":[2,3]},"headers":[],"relativePath":"yijing/zheng-yi-xin-fa/chapter-12.md","filePath":"yijing/zheng-yi-xin-fa/chapter-12.md","lastUpdated":1790647676000}'),c={name:"yijing/zheng-yi-xin-fa/chapter-12.md"},x=p({...c,setup(u){const o=[{id:"z12-01",label:"一、非特乾坤六子",showLabel:!0,sentences:[["健顺动入，陷丽止说。非特乾坤，六子",{text:"训释",glossary:"xunshi"},"。"]],note:["健、顺、动、入、陷、丽、止、说——这八个字不只是乾坤与六子的训释标签。（若只是八个标签，背下来就够了；麻衣要说的是：它们是**卦画结构的描述原则**。这一字之差，就是「只作八字说」（第四章）与「当求之于画象」的分野。）"]},{id:"z12-02",label:"二、不可专于八字",showLabel:!0,sentences:[["非特训释，盖谓不可专于八字上取也，当求之于画象。"]],note:["说「非特训释」，是说不可以只在这八个字上死板套用，应当从卦画中求取真义。（**从名词到动词的转变**：不是「乾叫做健」，而是「三画皆奇的结构，就是健的运作方式」——凡见三画皆奇，就知道有「健」象，不只是乾卦。）"]},{id:"z12-03",label:"三、八字的卦画定义",showLabel:!0,sentences:[["健谓三画奇也，顺谓三画纯偶是也，动谓一阳在二阴下是，入谓一阴在二阳下是，陷谓一阳在二阴中是，丽谓一阴在二阳中是，止则一阳在二阴之上是，说则一阴在二阳上是。"]],note:["健，是三爻皆奇（阳）；顺，是三爻皆偶（阴）；动，是一阳在二阴之下；入，是一阴在二阳之下；陷，是一阳在二阴之中；丽，是一阴在二阳之中；止，是一阳在二阴之上；说，是一阴在二阳之上。（规律很清楚：**异类爻在下 → 动／入；在中 → 陷／丽；在上 → 止／说**。位置本身就是意义——每一个定义都精确对应了卦画的**动态结构**，而不只是静态标签。例如坤「顺」是静态的承载，巽「入」却多了方向感：阴气从下方渗入阳气之中——这是风的运动，不是地的运动。）"]},{id:"z12-04",label:"四、多见于画象",showLabel:!0,sentences:[["凡此所论，多见于画象。"]],note:["凡此所论，都要从卦画之象中去看。（这是本章最重要的跃升：**八字可推广到六十四卦**——凡卦画中出现相同结构，就有相同的义理。不是「震＝动」这个等式，而是「一阳在二阴下＝动」这个结构原则，适用于所有含此结构的卦与爻。）"]},{id:"z12-05",label:"五、阖户与辟户",showLabel:!0,sentences:[["如",{text:"阖户",glossary:"hehu"},"谓之坤，则",{text:"姤",glossary:"gou"},"之初爻是；",{text:"辟户",glossary:"pihu"},"谓之乾，则",{text:"复",glossary:"fu"},"之初爻是。"]],note:["比如「阖户谓之坤」——姤卦的初爻（一阴生于下）就是这个象；「辟户谓之乾」——复卦的初爻（一阳生于下）就是这个象。（这是本章最精彩的一步：《系辞传》说「阖户谓之坤，辟户谓之乾」，讲的是**状态**（坤、乾整卦）；麻衣回到卦画，找到了更精确的**过程**——阴气刚刚闭合的那一刻是姤初爻，阳气刚刚开启的那一刻是复初爻。**过程比状态更有信息量**，这正是第六章「辞外见意」的具体实践：先找《系辞》的一个命题，不满足于文字理解，回到卦画找最精确的对应。）"]}],r=[{id:"xunshi",term:"训释",pinyin:"xùn shì",meaning:"训诂解释。指文字层面的义理概括。"},{id:"hehu",term:"阖户",pinyin:"hé hù",meaning:"关闭门户。坤象，阴气闭合。麻衣指姤之初爻——阴气刚刚闭合的那一刻。"},{id:"pihu",term:"辟户",pinyin:"pì hù",meaning:"开启门户。乾象，阳气开启。麻衣指复之初爻——阳气刚刚开启的那一刻。"},{id:"gou",term:"姤",pinyin:"gòu",meaning:"姤卦（上乾下巽），一阴生于下，夏至一阴生。此处取其初爻为「阖户」之象。"},{id:"fu",term:"复",pinyin:"fù",meaning:"复卦（上坤下震），一阳生于下，冬至一阳来复。此处取其初爻为「辟户」之象。"}];return(b,t)=>{const i=a("DaoTextReading"),l=a("DaoKeywordCards");return g(),d("div",null,[t[0]||(t[0]=s("",22)),e(i,{colophon:"健顺动入 · 陷丽止说 · 当求画象 · 阖辟在初爻",tone:"ink",density:"comfortable","default-mode":"slips","mode-switch":!0,"aria-label":"正易心法第十二章原文",sections:o,glossary:r}),t[1]||(t[1]=n("blockquote",null,[n("p",null,"注：本页依所据底本录入。原文「当求之于画象」的「画象」、以及末句引《系辞传》「阖户谓之坤，辟户谓之乾」皆随底本，不作统一。")],-1)),t[2]||(t[2]=n("h2",{id:"【原典层】字词释义",tabindex:"-1"},[h("【原典层】字词释义 "),n("a",{class:"header-anchor",href:"#【原典层】字词释义","aria-label":'Permalink to "【原典层】字词释义"'},"​")],-1)),e(l,{items:[{term:"八字非专属",pinyin:["bā","zì"],meaning:"健顺动入陷丽止说不是八卦的专属标签，而是「三画皆奇／一阳在二阴下」这类结构的通用描述原则。"},{term:"当求之于画象",pinyin:["huà","xiàng"],meaning:"八字的本义要从卦画结构中求取，而非死记标签——这是对第四章「只作八字说」的正面回应。"},{term:"入 与 顺",pinyin:["rù","shùn"],meaning:"坤为顺（静态承载），巽为入（动态渗透）。「入」多了一个方向感：阴气从下方渗入阳气之中，如风。"},{term:"阖户（姤初）",pinyin:["hé","hù"],meaning:"《系辞》「阖户谓之坤」讲的是状态（坤）；麻衣回到卦画，找到过程——阴气刚闭的那一刻即姤卦初爻。"},{term:"辟户（复初）",pinyin:["pì","hù"],meaning:"《系辞》「辟户谓之乾」；麻衣指复卦初爻——阳气刚开的那一刻（冬至一阳来复）。"}]}),t[3]||(t[3]=s("",25))])}}});export{y as __pageData,x as default};
